mapper.select:
SELECT name, COALESCE(SUM(value), 0) AS value FROM ( SELECT '平台手续费' AS name, COALESCE(SUM(t.platform_fee), 0) AS value FROM ( SELECT sr.id, sr.platform_fee FROM biz_sale_record sr LEFT JOIN biz_sale_item si ON si.sale_record_id = sr.id AND si.deleted = 0 LEFT JOIN biz_product p ON p.id = si.product_id AND p.deleted = 0 WHERE sr.deleted = 0 AND sr.business_date >= #{startDate} AND sr.business_date <= #{endDate}
GROUP BY sr.id, sr.platform_fee ) t UNION ALL SELECT '快递费' AS name, COALESCE(SUM(t.express_fee), 0) AS value FROM ( SELECT sr.id, sr.express_fee FROM biz_sale_record sr LEFT JOIN biz_sale_item si ON si.sale_record_id = sr.id AND si.deleted = 0 LEFT JOIN biz_product p ON p.id = si.product_id AND p.deleted = 0 WHERE sr.deleted = 0 AND sr.business_date >= #{startDate} AND sr.business_date <= #{endDate}
GROUP BY sr.id, sr.express_fee ) t UNION ALL SELECT '包装费' AS name, COALESCE(SUM(t.package_fee + t.other_expense), 0) AS value FROM ( SELECT sr.id, sr.package_fee, sr.other_expense FROM biz_sale_record sr LEFT JOIN biz_sale_item si ON si.sale_record_id = sr.id AND si.deleted = 0 LEFT JOIN biz_product p ON p.id = si.product_id AND p.deleted = 0 WHERE sr.deleted = 0 AND sr.business_date >= #{startDate} AND sr.business_date <= #{endDate}
GROUP BY sr.id, sr.package_fee, sr.other_expense ) t UNION ALL SELECT '其它费用' AS name, COALESCE(SUM(t.promotion_fee), 0) AS value FROM ( SELECT sr.id, sr.promotion_fee FROM biz_sale_record sr LEFT JOIN biz_sale_item si ON si.sale_record_id = sr.id AND si.deleted = 0 LEFT JOIN biz_product p ON p.id = si.product_id AND p.deleted = 0 WHERE sr.deleted = 0 AND sr.business_date >= #{startDate} AND sr.business_date <= #{endDate}
GROUP BY sr.id, sr.promotion_fee ) t
UNION ALL SELECT '其它费用' AS name, COALESCE(SUM(amount), 0) AS value FROM biz_expense WHERE deleted = 0 AND independent_flag = 1 AND expense_date >= #{startDate} AND expense_date <= #{endDate}
) t GROUP BY name ORDER BY value DESC
